// Theory is the Go interface backing the Gom sort Theory.
type Theory interface {
	sharedobjects.Term
	isTheory()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConsconcElementaryTheory() bool
	IsEmptyconcElementaryTheory() bool
	GetHeadconcElementaryTheory() ElementaryTheory
	GetTailconcElementaryTheory() Theory
	Length() int
	Reverse() Theory
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// TheoryFromTerm is Java Gom's Theory.fromTerm(trm).
func TheoryFromTerm(trm aterm.ATerm) Theory { return TheoryFromTermConv(trm, aterm.IdConverter{}) }

// TheoryFromTermConv is Java Gom's Theory.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func TheoryFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) Theory {
	converted := conv.Convert(trm)
	var results []Theory
	if r, ok := fromTermConcElementaryTheoryTheory(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a Theory", trm), IllegalArgument: true})
	}
	return results[0]
}

// TheoryFromString is Java Gom's Theory.fromString(s).
func TheoryFromString(s string) Theory { return TheoryFromTerm(aterm.GetInstance().Parse(s)) }

// TheoryFromStream is Java Gom's Theory.fromStream(stream) (an IOException is
// the error).
func TheoryFromStream(stream io.Reader) (Theory, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return TheoryFromTerm(at), nil
}

// ConcElementaryTheoryTheory is the term type of the variadic operator `concElementaryTheory(...)` of sort Theory
// (Java's abstract class concElementaryTheory): a maximally-shared cons cell (Java's
// ConsconcElementaryTheory: a head and a tail) or the empty list (Java's EmptyconcElementaryTheory).
type ConcElementaryTheoryTheory struct {
	head  ElementaryTheory
	tail  Theory
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcElementaryTheoryTheory) isTheory() {}

func (t *ConcElementaryTheoryTheory) Hash() uint32 { return t.hash }

func (t *ConcElementaryTheoryTheory) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcElementaryTheoryTheory)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcElementaryTheoryTheory) Duplicate() sharedobjects.Term {
	return &ConcElementaryTheoryTheory{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new ElementaryTheory[]{}): a last tail
// that is not a list (of sort Theory) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcElementaryTheoryTheory) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur Theory = t
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcElementaryTheoryTheory); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concElementaryTheory list is not a ElementaryTheory", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcElementaryTheoryTheory) ChildCount() int { return len(t.elements()) }

func (t *ConcElementaryTheoryTheory) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcElementaryTheoryTheory) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcElementaryTheoryTheory) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcElementaryTheoryFromArray(children).
func (t *ConcElementaryTheoryTheory) SetChildren(children []any) any {
	args := make([]ElementaryTheory, len(children))
	for i, c := range children {
		args[i] = c.(ElementaryTheory)
	}
	return MakeConcElementaryTheory(args...)
}

func (t *ConcElementaryTheoryTheory) String() string {
	var b strings.Builder
	b.WriteString("concElementaryTheory(")
	var cur Theory = t
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcElementaryTheory is Java Gom's ConsconcElementaryTheory.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcElementaryTheory(head ElementaryTheory, tail Theory) Theory {
	proto := &ConcElementaryTheoryTheory{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcElementaryTheory"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcElementaryTheoryTheory)
}

// realMakeEmptyConcElementaryTheory is Java Gom's EmptyconcElementaryTheory.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcElementaryTheory() Theory {
	proto := &ConcElementaryTheoryTheory{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcElementaryTheory"), nil)}
	return factory.Build(proto).(*ConcElementaryTheoryTheory)
}

// RawConcElementaryTheory builds the concElementaryTheory list holding exactly args, without construction
// hook.
func RawConcElementaryTheory(args ...ElementaryTheory) Theory {
	l := realMakeEmptyConcElementaryTheory()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcElementaryTheory(args[i], l)
	}
	return l
}

// EmptyConcElementaryTheory is Java Gom's EmptyconcElementaryTheory.make(): the empty concElementaryTheory list, after the
// construction hooks.
func EmptyConcElementaryTheory() Theory {
	return realMakeEmptyConcElementaryTheory()
}

// ConsConcElementaryTheory is Java Gom's ConsconcElementaryTheory.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcElementaryTheory(head ElementaryTheory, tail Theory) Theory {
	return RealMakeConsConcElementaryTheory(head, tail)
}

// MakeConcElementaryTheory builds the list of args as Tom's `concElementaryTheory(args…)` does: from EmptyConcElementaryTheory,
// by ConsConcElementaryTheory, through the construction hooks (Java's concElementaryTheory.fromArray).
func MakeConcElementaryTheory(args ...ElementaryTheory) Theory {
	var l Theory = EmptyConcElementaryTheory()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcElementaryTheory(args[i], l)
	}
	return l
}

// ConcElementaryTheoryFromArray is Java Gom's concElementaryTheory.fromArray(array).
func ConcElementaryTheoryFromArray(array []ElementaryTheory) Theory {
	return MakeConcElementaryTheory(array...)
}

