// SymbolName is the symbol of the Java term: ConsconcElementaryTheory or EmptyconcElementaryTheory.
func (t *ConcElementaryTheoryTheory) SymbolName() string {
	if t.empty {
		return "EmptyconcElementaryTheory"
	}
	return "ConsconcElementaryTheory"
}

func (t *ConcElementaryTheoryTheory) IsConsconcElementaryTheory() bool  { return !t.empty }
func (t *ConcElementaryTheoryTheory) IsEmptyconcElementaryTheory() bool { return t.empty }

func (t *ConcElementaryTheoryTheory) GetHeadconcElementaryTheory() ElementaryTheory {
	if t.empty {
		panic(&aterm.GomError{Msg: "This Theory has no HeadconcElementaryTheory"})
	}
	return t.head
}
func (t *ConcElementaryTheoryTheory) GetTailconcElementaryTheory() Theory {
	if t.empty {
		panic(&aterm.GomError{Msg: "This Theory has no TailconcElementaryTheory"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concElementaryTheory list counts as one element).
func (t *ConcElementaryTheoryTheory) Length() int {
	res := 0
	var tl Theory = t
	for {
		c, ok := tl.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcElementaryTheoryTheory); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concElementaryTheory list.
func (t *ConcElementaryTheoryTheory) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur Theory = t
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcElementaryTheoryTheory); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcElementaryTheory
// (through the hooks).
func (t *ConcElementaryTheoryTheory) Reverse() Theory {
	if t.empty {
		return t
	}
	var cur Theory = t
	var rev Theory = EmptyConcElementaryTheory()
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			break
		}
		rev = ConsConcElementaryTheory(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcElementaryTheory (through the hooks).
func (t *ConcElementaryTheoryTheory) Append(element ElementaryTheory) Theory {
	var heads []ElementaryTheory
	var cur Theory = t
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res Theory
	if c, ok := cur.(*ConcElementaryTheoryTheory); ok && c.empty {
		res = ConsConcElementaryTheory(element, cur)
	} else {
		res = ConsConcElementaryTheory(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcElementaryTheory(heads[i], res)
	}
	return res
}

func (t *ConcElementaryTheoryTheory) CompareTo(o any) int {
	for {
		ao := o.(Theory)
		if ao == Theory(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcElementaryTheoryTheory)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcElementaryTheoryTheory)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcElementaryTheoryTheory) CompareToLPO(o any) int {
	for {
		ao := o.(Theory)
		if ao == Theory(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcElementaryTheoryTheory)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcElementaryTheoryTheory)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcElementaryTheoryTheory) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []ElementaryTheory
	var cur Theory = t
	for {
		c, ok := cur.(*ConcElementaryTheoryTheory)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcElementaryTheoryTheory); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcElementaryTheoryTheory is Java Gom's concElementaryTheory.fromTerm: an application of concElementaryTheory, or a
// list (of ToATerm), of convertible elements.
func fromTermConcElementaryTheoryTheory(trm aterm.ATerm, conv aterm.ATermConverter) (res Theory, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concElementaryTheory" {
		elems := make([]ElementaryTheory, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ElementaryTheoryFromTermConv(a, conv)
		}
		return MakeConcElementaryTheory(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concElementaryTheory (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []ElementaryTheory
		for !list.IsEmpty() {
			elems = append(elems, ElementaryTheoryFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcElementaryTheory(elems...), true
	}
	return nil, false
}
